      "code": "\n# Power calculation for F-test of R-squared = 0 in linear regression\n# H₀: R² = 0 (all predictor coefficients zero)\n# H₁: R² ≠ 0 (at least one predictor coefficient nonzero)\n\n# Parameters\nN <- 80                # sample size (participants)\nR <- 0.30             # anticipated multiple correlation coefficient\np <- 3                # number of predictors (excluding intercept)\nalpha <- 0.05         # significance level\nn_p_minus_1 <- N - p - 1  # degrees of freedom for residual error\n\n# Calculate R-squared\nR_squared <- R^2\n\n# Test statistic under null: F ~ F(p, n-p-1)\n# Critical value at alpha level (one-tailed upper tail test)\nf_crit <- qf(alpha, df1 = p, df2 = n_p_minus_1, lower.tail = FALSE)\n\n# Noncentrality parameter under the alternative\n# λ = R² * n / (1 - R²)\nlambda <- (R_squared * N) / (1 - R_squared)\n\n# Power: P(F > F_critical | λ)\n# Use noncentral F distribution\npower <- pf(f_crit, df1 = p, df2 = n_p_minus_1, ncp = lambda, lower.tail = FALSE)\n\n# Create results object\nresults <- list(\n  power = power,\n  R_squared = R_squared,\n  noncentrality_parameter = lambda,\n  critical_f_value = f_crit,\n  df1 = p,\n  df2 = n_p_minus_1\n)\n\n# Format output\ncat(\"=== Power Analysis: F-Test of R² = 0 ===\\n\")\ncat(sprintf(\"Sample size (N): %d participants\\n\", N))\ncat(sprintf(\"Multiple correlation (R): %.2f\\n\", R))\ncat(sprintf(\"R-squared (effect size): %.4f\\n\", R_squared))\ncat(sprintf(\"Number of predictors (p): %d\\n\", p))\ncat(sprintf(\"Degrees of freedom: F(%d, %d)\\n\", p, n_p_minus_1))\ncat(sprintf(\"Significance level (α): %.3f\\n\", alpha))\ncat(sprintf(\"Noncentrality parameter (λ): %.4f\\n\", lambda))\ncat(sprintf(\"Critical F-value: %.4f\\n\", f_crit))\ncat(sprintf(\"\\n*** POWER (probability): %.4f ***\\n\", power))\n\n# JSON output\njsonlite::toJSON(\n  list(\n    results = list(\n      list(metric = \"power\", value = round(power, 4), unit = \"probability\"),\n      list(metric = \"R-squared\", value = round(R_squared, 4), unit = \"unitless\"),\n      list(metric = \"noncentrality parameter\", value = round(lambda, 4), unit = \"unitless\"),\n      list(metric = \"critical F-value\", value = round(f_crit, 4), unit = \"unitless\"),\n      list(metric = \"degrees of freedom numerator\", value = p, unit = \"count\"),\n      list(metric = \"degrees of freedom denominator\", value = n_p_minus_1, unit = \"count\")\n    )\n  ),\n  auto_unbox = TRUE,\n  digits = 15\n)\n",
