      "code": "\n# Independent verification of the F-test power calculation for R² = 0\n# Parameters from the original request\nN <- 80              # sample size\nR <- 0.30            # multiple correlation coefficient\np <- 3               # number of predictors (excluding intercept)\nalpha <- 0.05        # significance level\n\n# ============================================================================\n# CHECK 1: Formula for F-test statistic and noncentrality parameter\n# ============================================================================\n# The global F-test of R² = 0 tests whether all regression coefficients\n# (excluding intercept) are simultaneously zero.\n#\n# Test statistic: F = [R² / p] / [(1 - R²) / (n - p - 1)]\n#               = R² * (n - p - 1) / [p * (1 - R²)]\n#\n# Under H₀: R² = 0, F ~ F(p, n - p - 1) (central F)\n# Under H₁: R² ≠ 0, F ~ F(p, n - p - 1, λ) (noncentral F)\n#\n# Noncentrality parameter: λ = R² * n / (1 - R²)\n# (This is derived from the ratio of variance explained to residual variance)\n\nR_squared <- R^2\ncat(\"R² =\", R_squared, \"\\n\")\n\n# Degrees of freedom\ndf1 <- p                  # numerator df\ndf2 <- N - p - 1          # denominator df\ncat(\"Numerator df (p):\", df1, \"\\n\")\ncat(\"Denominator df (n - p - 1):\", df2, \"\\n\")\n\n# Critical F-value at α = 0.05 (upper tail)\nF_crit <- qf(alpha, df1, df2, lower.tail = FALSE)\ncat(\"Critical F-value at α =\", alpha, \":\", F_crit, \"\\n\")\n\n# Noncentrality parameter\nlambda <- (R_squared * N) / (1 - R_squared)\ncat(\"Noncentrality parameter λ:\", lambda, \"\\n\")\n\n# Power = P(F > F_crit | λ)\n# Use noncentral F CDF: pf(q, df1, df2, ncp) gives P(F ≤ q)\n# So power = 1 - pf(F_crit, df1, df2, ncp) = pf(F_crit, df1, df2, ncp, lower.tail=FALSE)\npower_check <- pf(F_crit, df1, df2, ncp = lambda, lower.tail = FALSE)\ncat(\"\\nPower (check 1 - direct noncentral F):\", power_check, \"\\n\")\n\n# ========================================================================