ct)\n# n = 80, p = 3\n# We expect power to be modest but reasonable (typically 50-80% range)\n# Power should be > 0.5 (better than coin flip for a notable effect)\n\ncat(\"\\n=== SANITY CHECKS ===\\n\")\ncat(\"R² = 0.09 represents a small-to-moderate effect\\n\")\ncat(\"n = 80 is a reasonable sample size\\n\")\ncat(\"Power ≈\", round(power_check, 4), \"≈\", round(power_check * 100, 1), \"% is plausible\\n\")\n\n# The power should increase with:\n#   - Larger R (larger effect size)\n#   - Larger N (more data)\n#   - Smaller p (fewer predictors to estimate)\n#   - Larger alpha (less stringent threshold)\n\ncat(\"\\nPower is >50% but <80%, which is reasonable for a small effect\\n\")\ncat(\"size (R = 0.30) and moderate sample size (N = 80).\\n\")\n\n# ============================================================================\n# FINAL VERIFICATION\n# ============================================================================\ncat(\"\\n=== FINAL RESULTS ===\\n\")\ncat(\"Sample size (N):\", N, \"\\n\")\ncat(\"Multiple correlation (R):\", R, \"\\n\")\ncat(\"R-squared:\", R_squared, \"\\n\")\ncat(\"Number of predictors (p):\", p, \"\\n\")\ncat(\"Significance level (α):\", alpha, \"\\n\")\ncat(\"Degrees of freedom: F(\", df1, \",\", df2, \")\\n\", sep=\"\")\ncat(\"Critical F-value:\", F_crit, \"\\n\")\ncat(\"Noncentrality parameter (λ):\", lambda, \"\\n\")\ncat(\"POWER:\", power_check, \"\\n\")\n\n# Compare with original result\noriginal_power <- 0.6238\ndifference <- abs(power_check - original_power)\ncat(\"\\nOriginal calculated power:\", original_power, \"\\n\")\ncat(\"Verification power:\", power_check, \"\\n\")\ncat(\"Difference:\", difference, \"\\n\")\ncat(\"Match: \", difference < 0.0001, \"\\n\", sep=\"\")\n\n# JSON output for structured comparison\ncat(\"\\nJSON verification output:\\n\")\njsonlite::toJSON(\n  list(\n    verification = list(\n      power_verified = round(power_check, 4),\n      power_original = original_power,\n      critical_f_value = round(F_crit, 4),\n      noncentrality_parameter = round(lambda, 4),\n      df1 = df1,\n      df2 = df2,\n      match = abs(power_check - original_power) < 0.0001\n    )\n  ),\n  auto_unbox = TRUE,\n  digits = 15\n)\n",
